@import "tailwindcss";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
}

.raya-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: var(--raya-button-height, 2.25rem);
  padding-inline: var(--raya-button-px, 1rem);
  font-size: var(--raya-button-font-size, 0.875rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  background: var(--raya-button-bg, var(--primary));
  color: var(--raya-button-fg, var(--primary-foreground));
  border: 1px solid var(--raya-button-border, transparent);
  border-radius: var(--radius-md, 0.375rem);
  cursor: pointer;
}

.raya-button:hover {
  opacity: 0.9;
}

.raya-card {
  display: flex;
  flex-direction: column;
  gap: var(--raya-card-gap, 1rem);
  padding: var(--raya-card-padding, 1.5rem);
  font-family: var(--font-sans, ui-sans-serif, system-ui);
  background: var(--card);
  color: var(--card-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg, 0.625rem);
}

.raya-badge {
  display: inline-flex;
  align-items: center;
  padding-inline: var(--raya-badge-px, 0.625rem);
  padding-block: var(--raya-badge-py, 0.25rem);
  font-size: var(--raya-badge-font-size, 0.75rem);
  line-height: 1;
  background: var(--secondary);
  color: var(--secondary-foreground);
  border-radius: 9999px;
}

.raya-avatar {
  width: var(--raya-avatar-size, 2rem);
  height: var(--raya-avatar-size, 2rem);
  border-radius: var(--raya-avatar-radius, 9999px);
  background: var(--accent);
  color: var(--accent-foreground);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
